with parsed as (select id, customer_id, aggregate(items, cast(0 as double), (acc, i) -> acc + i.qty * i.price, acc -> round(acc, 2)) as cart_value, ship_to.zip as ship_zip from carts where customer_id is null) select *, ntile(10) over (partition by customer_id order by cart_value asc, id asc) as cart_value_bucket, ntile(10) over (partition by customer_id order by cart_value asc, id asc) as cart_value_bucket_2, ntile(10) over (partition by customer_id order by cart_value asc, id asc) as cart_value_bucket_3 from parsed
